def run(_context):
    # Adaptive rough: cap stepdown, leave finish stock
    r1 = mb.set_params("2D Adaptive1", {
        "maximumStepdown": {"value": 10, "unit": "mm"},
        "stockToLeave": {"value": 0.3, "unit": "mm"},
        "verticalStockToLeave": {"value": 0.1, "unit": "mm"},
    })
    # Pocket finish: no stock to leave, single depth cleanup
    r2 = mb.set_params("2D Pocket1", {
        "useStockToLeave": {"value": False, "unit": "bool"},
        "tolerance": {"value": 0.01, "unit": "mm"},
    })
    # Outer contour: multiple depths down the 50 mm sides
    r3 = mb.set_params("2D Contour1", {
        "doMultipleDepths": {"value": True, "unit": "bool"},
        "maximumStepdown": {"value": 10, "unit": "mm"},
    })
    print("ok", len(r1), len(r2), len(r3))

